insert into invoices(id,org_id,client_id,number,status) values('b9000000-0000-4000-8000-000000000004','b9000000-0000-4000-8000-000000000002','b9000000-0000-4000-8000-000000000003','Synthetic draft','draft');
insert into invoice_items(org_id,invoice_id,description,quantity,unit_price_satang) values('b9000000-0000-4000-8000-000000000002','b9000000-0000-4000-8000-000000000004','Synthetic service',1,101);
select set_config('request.jwt.claims','{"role":"authenticated","sub":"b9000000-0000-4000-8000-000000000001"}',true);
set local role authenticated;
select throws_ok($$update invoices set status='sent' where id='b9000000-0000-4000-8000-000000000004'$$,'P0001','Invoice issuance requires the issue command','direct draft issuance denied');
select throws_ok($$insert into invoices(org_id,client_id,number,status) values('b9000000-0000-4000-8000-000000000002','b9000000-0000-4000-8000-000000000003','Forged sent','sent')$$,'P0001','New invoice must be draft','direct sent creation denied');
select throws_ok($$update invoices set status='overdue' where id='b9000000-0000-4000-8000-000000000004'$$,'P0001','Payable state requires issue command','draft cannot bypass issue through overdue');
reset role;
update invoices set status='draft' where id='b9000000-0000-4000-8000-000000000004';
select update_business_profile('b9000000-0000-4000-8000-000000000002','Synthetic seller','Synthetic address',null,'unknown');
create temp table evidence_result(kind text,id uuid);grant all on evidence_result to authenticated;
set local role authenticated;
select throws_ok($$select issue_invoice('b9000000-0000-4000-8000-000000000002','b9000000-0000-4000-8000-000000000004',1,'b9000000-0000-4000-8000-000000000010')$$,'P0001','Draft at expected version required','stale version cannot issue');
insert into evidence_result select 'snapshot',issue_invoice('b9000000-0000-4000-8000-000000000002','b9000000-0000-4000-8000-000000000004',(select version from invoices where id='b9000000-0000-4000-8000-000000000004'),'b9000000-0000-4000-8000-000000000011');
select is((select snapshot->'document'->>'totalSatang' from invoice_snapshots where id=(select id from evidence_result where kind='snapshot')),'101','snapshot preserves exact satang');
select is((select snapshot->>'kind' from invoice_snapshots where id=(select id from evidence_result where kind='snapshot')),'operational_invoice','document classification explicit');
select throws_ok($$update invoice_items set description='Changed after issue' where invoice_id='b9000000-0000-4000-8000-000000000004'$$,'P0001','Issued or payment evidence locks invoice lines','issued lines cannot mutate');
select throws_ok($$update invoices set amount_satang=1 where id='b9000000-0000-4000-8000-000000000004'$$,'P0001','Retained invoice amount cannot be overwritten','issued amount tampering rejected');
select throws_ok($$update invoices set notes='Changed after issue' where id='b9000000-0000-4000-8000-000000000004'$$,'P0001','Issued content is frozen; use linked correction','issued header cannot mutate');
select throws_ok($$update invoices set status='cancelled' where id='b9000000-0000-4000-8000-000000000004'$$,'P0001','Issued invoice cancellation requires linked correction','issued cancellation cannot bypass correction');
select throws_ok($$update invoices set status='draft' where id='b9000000-0000-4000-8000-000000000004'$$,'P0001','Issued invoice cannot return to draft','issued invoice cannot disappear from AR');
select is(issue_invoice('b9000000-0000-4000-8000-000000000002','b9000000-0000-4000-8000-000000000004',(select source_version from invoice_snapshots where id=(select id from evidence_result where kind='snapshot')),'b9000000-0000-4000-8000-000000000011'),(select id from evidence_result where kind='snapshot'),'same-key issued retry durable');
insert into evidence_result select 'claim',submit_internal_payment_claim('b9000000-0000-4000-8000-000000000002','b9000000-0000-4000-8000-000000000004',101,'Synthetic receipt report','b9000000-0000-4000-8000-000000000012');
select is((select count(*)::int from payments where org_id='b9000000-0000-4000-8000-000000000002'),0,'staff report cannot settle');
select throws_ok($$select review_payment_claim_with_evidence('b9000000-0000-4000-8000-000000000002',(select id from evidence_result where kind='claim'),101,'Synthetic actual bank evidence','b9000000-0000-4000-8000-000000000020','verified','-infinity','cash')$$,'P0001','Invalid verification evidence','nonfinite bank date rejected');
select is((select count(*)::int from payments where org_id='b9000000-0000-4000-8000-000000000002'),0,'invalid bank date writes no cash');
select throws_ok($$select reconcile_legacy_payment_with_evidence('b9000000-0000-4000-8000-000000000002','b9000000-0000-4000-8000-000000000099',101,'Synthetic actual bank evidence','b9000000-0000-4000-8000-000000000021','-infinity','cash')$$,'P0001','Invalid reconciliation evidence','legacy reconciliation rejects nonfinite date before write');
insert into evidence_result select 'receipt',review_payment_claim_with_evidence('b9000000-0000-4000-8000-000000000002',(select id from evidence_result where kind='claim'),101,'Synthetic actual bank evidence','b9000000-0000-4000-8000-000000000013','verified','2026-07-02','cash');
select is((select (paid_at at time zone 'Asia/Bangkok')::date::text from payments where id=(select id from evidence_result where kind='receipt')),'2026-07-02','actual bank date retained');
select is((select method::text from payments where id=(select id from evidence_result where kind='receipt')),'cash','actual method retained');
select is((select status::text from invoices where id='b9000000-0000-4000-8000-000000000004'),'paid','receipt atomically settles');
select is((select count(*)::int from payment_allocations where org_id='b9000000-0000-4000-8000-000000000002'),1,'one allocation');
select is(review_payment_claim_with_evidence('b9000000-0000-4000-8000-000000000002',(select id from evidence_result where kind='claim'),101,'Synthetic actual bank evidence','b9000000-0000-4000-8000-000000000013','verified','2026-07-02','cash'),(select id from evidence_result where kind='receipt'),'verified receipt retry durable');
